    "sourceHash": "sha256:1c60429fe57f05cd901c33037077845c7f54b8b003d41eacb0bb0f6d0dc3d318",
    "translatableHash": "sha256:ccd54ad70252be2efd424129ca7b2d674de30131d0312318bc0316ef64df2045",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Echoes of the End",
      "level": 20,
      "rarity": "unique",
      "size": "large",
      "traits": [
        "haunt",
        "mythic"
      ],
      "description": "An overwhelming trumpeting fills the area as the apocalypse seed vibrates and shakes off the encrusted bone that's accreted around it to reveal a large tooth fragment from some immense monster.",
      "armorClass": 0,
      "hitPoints": 0,
      "hardness": 0,
      "stealth": {
        "modifier": 38,
        "details": "(legendary) to notice the low vibration forming in the area surrounding the apocalypse seed; noticing the apocalypse seed itself has a DC of 0"
      },
      "disable": "check (arcana, dc:50) (master), check (occultism, dc:50) (legendary), or check (religion, dc:50) (legendary) to recognize and shore up the area against the localized planar instability causing a connection between the apocalypse seed and Jandelay, or check (athletics, dc:53) (legendary) to grasp the apocalypse seed and muffle its vibrations with your embrace. Four successes are needed to muffle the aura enough against the planar instability and end the hazard.",
      "isComplex": true,
      "routine": "(1 action) Each creature in the area must attempt a check (fortitude, dc:44) save. A creature with the slowed condition from this hazard takes a –2 penalty to this save.\nCritical Success The creature is unaffected.\nSuccess The creature takes 2d10+10 sonic damage.\nFailure The creature takes 4d10+20 sonic damage and is Slowed 1 until the start of the hazard's next turn.\nCritical Failure The creature takes 8d10+40 sonic damage and is Slowed 2 for 1 round.",
      "reset": "The apocalypse seed creates another area of instability after 24 hours.",
      "saves": {
        "fortitude": 0,
        "reflex": 0,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "QTqrLsbtEptA0oWy",
          "name": "Oliphaunt's Echo",
          "kind": "reaction",
          "description": "Trigger A living creature enters area C6\nEffect Pent-up magical energy from another world begins to release in waves of overwhelming sound. The hazard rolls initiative.",
          "traits": []
        }
      ]
    }
