    "sourceHash": "sha256:8e906607e47cf42d761141cb15494d8ef4df2338f1cc78f42a66a9b39542f09d",
    "translatableHash": "sha256:4bf27ded0b226e5e1c81e94152f38107f4b6e1f28f59afb4a539fc778ebedc71",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Disgruntled Diners",
      "level": 6,
      "rarity": "unique",
      "size": "large",
      "traits": [
        "haunt"
      ],
      "description": "Phantasmal diners begin hurling phantom food and very real, sharp cutlery in a dangerous food fight that targets intruders.",
      "armorClass": 0,
      "hitPoints": 0,
      "hardness": 0,
      "stealth": {
        "modifier": 15,
        "details": "(expert)"
      },
      "disable": "check (intimidation, dc:25) (trained) to threaten the ghostly guests into submission or check (religion, dc:28) (expert) to exorcise the haunt; two successes are required to disable it.",
      "isComplex": true,
      "routine": "(1 action) On the haunt's initiative, the phantoms hurl ghostly food and real silverware through the room. All creatures other than Ilza who are in the area take 2d8+9 piercing damage (check (reflex, dc:24, basic, options:area-effect) save) from the sharp forks and knives being thrown about.",
      "reset": "The haunt deactivates at the start of any round in which Ilza is the only other creature present, then immediately resets.",
      "saves": {
        "fortitude": 0,
        "reflex": 0,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "8oskjqUGlGRMs133",
          "name": "Any Excuse for a Food Fight",
          "kind": "reaction",
          "description": "Trigger Ilza attacks the PCs\nEffect Upon seeing Ilza's anger, the guests rise up in a flurry of activity, their voices suddenly loud and startling. Every PC in area D6 must succeed at a check (will, dc:24, options:area-effect,inflicts:off-guard) save or become Off-Guard for the first round of combat. The haunt then rolls initiative.",
          "traits": []
        }
      ]
    }
