    "translatableHash": "sha256:f9a149b1823ee771597bf631d0aa9710dbc2ca9e0cf45dc53aab6ebfc9dbee66",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Poisoned Skull",
      "level": 8,
      "rarity": "common",
      "size": "large",
      "traits": [
        "trap"
      ],
      "description": "A fast-acting toxin that's almost invisible to the eye coats the first and seventh skull on this display shelf.",
      "armorClass": 0,
      "hitPoints": 0,
      "hardness": 0,
      "stealth": {
        "modifier": 18,
        "details": "(expert)"
      },
      "disable": "check (thievery, dc:31) to identify the toxin and delicately wipe it free before burning the tainted cloth; on a critical success, the character can pinpoint two areas where the skull can be safely carried and, perhaps, used as an improvised thrown weapon to poison a creature.",
      "isComplex": false,
      "routine": "",
      "reset": "",
      "saves": {
        "fortitude": 0,
        "reflex": 0,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "Ihswa1kkuRMM0TJP",
          "name": "Stain and Pain",
          "kind": "reaction",
          "description": "Trigger A creature comes in contact with the skull\nEffect The contact poison turns the exposed flesh a deep scarlet color that persists for 24 hours and also afflicts the creature with nettleweed residue.\nSaving Throw check (fortitude, dc:27, traits:poison)\nOnset 1 minute\nMaximum Duration 6 minutes\nStage 1 3d6 poison damage (1 minute)\nStage 2 4d6 poison damage (1 minute)\nStage 3 6d6 poison damage (1 minute)",
          "traits": []
        }
      ]
    }
