      "attacks": [
        {
          "id": "qfMeeXgzbn6RpRMz",
          "name": "Claw",
          "bonus": 26,
          "damage": "3d6+11 slashing; 2d6 spirit",
          "traits": [
            "agile",
            "finesse",
            "reach-10"
          ]
        }
      ],
      "actions": [
        {
          "id": "E3Bge0XIoRbFTgxZ",
          "name": "Easy to Call",
          "kind": "passive",
          "description": "A mymnian's level is considered 2 lower for the purpose of being conjured by the Binding Circle ritual (and potentially other rituals, at the GM's discretion), but it is always free to attack or leave instead of negotiate unless the primary caster's check is a critical success.",
          "traits": []
        },
        {
          "id": "dRc1PaMjFt0ZzYyY",
          "name": "Watchful Presence",
          "kind": "passive",
          "description": "60 feet. Even when a mymnian doesn't notice you, you feel like they—or something worse—are watching. A creature that begins its turn inside the aura feels an overwhelming sense of being watched, gaining a +2 status bonus to Perception checks but taking a –2 penalty to saving throws against fear effects. A creature in the aura can't reduce the value of its frightened condition below 1.",
          "traits": [
            "aura",
            "divine",
            "emotion",
            "fear",
            "mental",
            "visual"
          ]
        },
        {
          "id": "5hy5izhEbWcyWzlA",
          "name": "Doomed to Rise",
          "kind": "passive",
          "description": "A creature that dies from an attack by a mymnian while frightened becomes a ghost within the next 24 hours.",
          "traits": []
        },
        {
          "id": "cIO8t6NAMmj8wuLE",
          "name": "Extract Ghost",
          "kind": "action",
          "description": "Frequency once per round\nEffect The mymnian attempts a claw Strike. If it hits, it deals no damage—instead, the mymnian's claws hook onto the target's soul and, for a moment, tug it out of the body so that the victim can catch a glimpse of how it will look after it dies. The target takes 5d8 mental damage with a check (will, dc:33, options:damaging-effect,inflicts:frightened) save.\nCritical Success The target takes no damage.\nSuccess The target takes half damage.\nFailure The target takes full damage and becomes Frightened 1.\nCritical Failure The target takes double damage and becomes Frightened 2.",
          "traits": [
            "divine",
            "emotion",
            "fear",
            "mental"
          ]
        }
      ],
