      "rarity": "unique",
      "size": "large",
      "traits": [
        "mechanical"
      ],
      "description": "Hinged boards prop the massive paving stones into place on the causeway.",
      "armorClass": 0,
      "hitPoints": 0,
      "hardness": 0,
      "stealth": {
        "modifier": 22,
        "details": "(expert)"
      },
      "disable": "check (crafting, dc:27) (expert) to reinforce the stones of this causeway or check (thievery, dc:29) (master) to jam the hinges on the boards",
